import './style.css';
import {captureLibrary,exportLibrary,importLibrary,librarySources,restoreLibrary,bindLibraryRestore,sourceFromRaw,type Library} from './library.ts';
import {previouslyGrantedMIDI,chooseMIDIPorts} from './midi-permission.ts';

import {createProject,clone,factory,changePad,exportProject,importProject,toBase64,fromBase64,references,type Project,type Pad} from './model.ts';

import {EMBEDDED,FACTORY,LANE_FX,MASTER_FX,LANE_PARAMS,MASTER_PARAMS} from './metadata.ts';

import {ZONES} from './zones.ts';

import {decodeIMA,preparePCM,sampleCRC,waveformEnvelope,wavPCM16} from './audio.ts';

import {Device,MidiTransport,type State,type Save,type Sample} from './device.ts';
import {hex,saveProtectionReason,type ProjectNorDiagnosis,type SampleNorDiagnosis} from './nor-diagnostics.ts';

import {OP,concat,le16,u32,ascii,crc32,verifyProjectWire,ProtocolError,type InputPort,type OutputPort} from './protocol.ts';

const app=document.querySelector<HTMLDivElement>('#app')!;

const pages=['Dashboard','Kits & Pads','Samples','Lane FX','Master FX','Sequencer','Projects','Settings'];

let p:Project=createProject(),dirty=false,page=0,device:Device|null=null,access:MIDIAccess|null=null,state:State|null=null,save:Save|null=null,deviceSamples:Sample[]=[],error='',notice='Create offline. Connect when ready.',busy=false,progress=0,runtimeAck=false,lastRevision=0,selectedSample=14,category='ALL',eventStep=0,projectSlot=0,recoveryObject=7,recovery:{crc:number;token:number}|null=null;

let libraryArchive:Library|null=null;
let norProject:ProjectNorDiagnosis|null=null,sampleNorReports:SampleNorDiagnosis[]=[];
let norProjectBackup:Uint8Array|null=null,norSampleBackups:{bank:number;offset:number;crc32:number;data:Uint8Array}[]=[];
let inputId='',outputId='',context:AudioContext|null=null,embeddedBytes:Uint8Array|null=null,wav:{channels:Float32Array[];rate:number;duration:number;name:string}|null=null,trimStart=0,trimEnd=0,importRate=22050;

try{const stored=localStorage.getItem('fm1-drum-project');if(stored){p=importProject(stored);eventStep=p.bank*16;dirty=true;notice='Local project recovered. Device has not been changed.';}}catch{notice='Local cache could not be read. Import a saved editor project.';}

const esc=(s:unknown)=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]!));

const selected=(a:unknown,b:unknown)=>a===b?' selected':'';

const writeActions=new Set(['sync','save-auto','play','stop','record','factory','user-save','user-load','audition','source-audition','upload','delete-device','project-save','project-load','recovery-authorize','settings-send','library-restore']);
const button=(a:string,label:string,extra='')=>`<button data-action="${a}" ${extra} ${device?.readOnly&&writeActions.has(a)?'disabled title="Diagnostics-only: complete a successful Pull before device changes"':''}>${label}</button>`;

const offline=()=>!device;const disabled=()=>busy?'disabled':'';
const userSlots=()=>device?.caps?.userSlots??16;
const userCapacity=(id=selectedSample)=>deviceSamples.find(s=>s.id===(id<55?55:id))?.capacity??device?.caps?.capacity??19968;
const sampleLocked=(id:number)=>device?.caps?.userSlots===16&&!!((deviceSamples.find(s=>s.id===id)?.flags??0)&4);

const name=(id:number)=>id<55?EMBEDDED[id]?.name??'MISSING':p.samples.find(s=>s.id===id)?.name??deviceSamples.find(s=>s.id===id)?.name??`USER ${id-54} / MISSING`;

function persist(){try{localStorage.setItem('fm1-drum-project',exportProject(p));}catch{notice='Local cache full. Export the project file to retain these edits.';}}

function status(){
 const el=document.querySelector('#status');if(el)el.innerHTML=`<span><strong>${dirty?'LOCAL DIRTY':'LOCAL READY'}</strong> · ${device?(runtimeAck?'RUNTIME ACK · ':'')+(save?.state===1?'DEVICE SAVED':save?.state===2?'SAVE FAILED · '+esc(save.name):'COMMIT PENDING'):'OFFLINE / DEVICE UNCHANGED'}</span><span>${busy?'TRANSFER '+Math.round(progress*100)+'%':esc(notice)}</span>`;
 const lcd=document.querySelector('.statusbig');if(lcd){lcd.textContent=!device?'OFFLINE':save?.state===1?'SAVED':save?.state===2?'NO SAVE':'WAIT';const description=lcd.nextElementSibling;if(description)description.textContent=!device?'No device connected. Offline edits stay in this browser and exported files.':save?.state===2?[save.name,saveProtectionReason(save,norProject)].filter(Boolean).join(' — '):save?.state===1?'Last checked DEVICE snapshot is durable. Local dirty data may differ.':'Runtime awaits safe STOP, idle and write interval.';}
 document.querySelectorAll('.stat').forEach(row=>{if(row.firstElementChild?.textContent==='Last error'&&row.lastElementChild)row.lastElementChild.textContent=save?save.name+' / raw '+save.raw:'Not read';});
}

function changed(){dirty=true;runtimeAck=false;persist();status();}
/** Prepare a user sample entirely in the browser. Never bypass device capacity/CRC checks. */
function prepareImported(autoFit:'quality'|'duration'|null=null){
 if(!wav)throw Error('Choose a WAV first.');
 if(selectedSample<55)selectedSample=55;
 if(sampleLocked(selectedSample))throw Error('This USER slot is protected by overlapping legacy data. Select another slot.');
 const capacity=userCapacity(selectedSample);
 if(!Number.isFinite(capacity)||capacity<2)throw Error('Invalid sample slot capacity');
 let rate=importRate,start=trimStart,end=trimEnd;
 const maxFrames=capacity*2;
 if(autoFit){
  const remaining=Math.max(0,end-start);
  if(remaining<=0)throw Error('Select a non-empty source range.');
  if(autoFit==='quality'){
   rate=22050;
  }else{
   rate=[22050,16000,8000].find(r=>Math.floor(remaining*r)<=maxFrames)??8000;
  }
  // Leave a two-frame margin for rounding in floating point resampling.
  const maxDuration=(maxFrames-2)/rate;
  end=Math.min(end,start+maxDuration);
 }
 const pcm=preparePCM(wav.channels,wav.rate,rate,start,end),encoded=sampleCRC(pcm);
 if(encoded.adpcm.length>capacity)throw Error(`Source exceeds slot limit (${capacity} ADPCM bytes). Select Auto-fit or trim manually.`);
 const sample={id:selectedSample,name:wav.name.replace(/[^ -~]/g,'').replace(/\.wav$/i,'').slice(0,8).padEnd(1,'_'),rate,frames:pcm.length,crc:encoded.crc,adpcm:toBase64(encoded.adpcm)};
 p.samples=p.samples.filter(x=>x.id!==sample.id);p.samples.push(sample);
 importRate=rate;trimStart=start;trimEnd=end;changed();
 const cropped=wav.duration-end>0.005;
 notice=`Converted to mono ${rate} Hz / ${pcm.length} frames / ${encoded.adpcm.length} ADPCM bytes (${capacity} max). ${cropped?'Tail shortened to fit; preview before upload.':'Full selected range retained.'} Device not modified.`;
 render();
}


function download(data:Uint8Array|string,filename:string,type='application/octet-stream'){const part=typeof data==='string'?data:new Uint8Array(data).buffer;const url=URL.createObjectURL(new Blob([part],{type}));const a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),5000);}

function audioContext(){return context??(context=new AudioContext());}

async function source(id:number){const local=p.samples.find(s=>s.id===id);if(local)return {pcm:decodeIMA(fromBase64(local.adpcm),local.frames),rate:local.rate};if(id>=55)throw Error('Download this device sample first, or import its WAV offline.');if(!embeddedBytes)embeddedBytes=new Uint8Array(await (await fetch(import.meta.env.BASE_URL+'embedded-adpcm.bin')).arrayBuffer());const z=ZONES[id];return {pcm:decodeIMA(embeddedBytes.slice(z.offset,z.offset+Math.ceil(z.frames/2)),z.frames),rate:z.rate};}

async function preview(id:number,pad?:Pad){const {pcm,rate}=await source(id),ctx=audioContext();await ctx.resume();const b=ctx.createBuffer(1,pcm.length,rate);b.copyToChannel(new Float32Array(pcm),0);const s=ctx.createBufferSource(),gain=ctx.createGain();s.buffer=b;s.playbackRate.value=pad?2**(pad.tune/12):1;gain.gain.value=.35*(pad?pad.level/127:1);s.connect(gain).connect(ctx.destination);s.start(0,pad?pad.start*pcm.length/rate/100:0,pad?(pad.end-pad.start)*pcm.length/rate/100:pcm.length/rate);notice='Dry source preview; firmware FX are not simulated.';status();}

async function wave(){const c=document.querySelector<HTMLCanvasElement>('#wave');if(!c)return;const ctx=c.getContext('2d')!;c.width=900;c.height=150;ctx.fillStyle='#391210';ctx.fillRect(0,0,900,150);try{const {pcm}=await source(selectedSample);ctx.strokeStyle='#F87905';ctx.beginPath();waveformEnvelope(pcm,900).forEach(([lo,hi],x)=>{ctx.moveTo(x,75-lo*68);ctx.lineTo(x,75-hi*68);});ctx.stroke();const pad=p.pads[p.selectedPad];if(pad.sampleId===selectedSample){ctx.strokeStyle='#CFC5AB';[pad.start,pad.end].forEach(v=>{ctx.beginPath();ctx.moveTo(v*9,0);ctx.lineTo(v*9,150);ctx.stroke();});}}catch{ctx.fillStyle='#F87905';ctx.font='14px monospace';ctx.fillText('No local audio. Import or download the source.',20,80);}}

const timers=new Map<string,ReturnType<typeof setTimeout>>();

function live(key:string,fn:(d:Device)=>Promise<unknown>){if(!device||device.readOnly)return;clearTimeout(timers.get(key));timers.set(key,setTimeout(()=>{if(!device||busy)return;fn(device).then(()=>{runtimeAck=true;notice='Runtime ACK. Persistent status is polled separately.';status();}).catch(e=>{error=String(e.message??e);render();});},220));}

async function run(job:()=>Promise<unknown>){if(busy)return;busy=true;progress=0;error='';render();try{await job();}catch(e){error=e instanceof Error?e.message:String(e);}finally{busy=false;progress=0;render();}}

async function pull(){if(!device)return;const d=device,r=await d.pull(p),list=await d.sampleList(),verified=await d.saveStatus();p=r.project;state=r.state;lastRevision=state.revision;deviceSamples=list;save=verified;d.readOnly=false;dirty=false;runtimeAck=true;persist();notice='Device runtime read. No NOR write requested.';}

async function authorize(automatic=false){if(!('requestMIDIAccess'in navigator))throw Error('This browser lacks Web MIDI. Use a browser supporting Web MIDI SysEx; offline editing remains available.');access=await navigator.requestMIDIAccess({sysex:true});if(!access.sysexEnabled)throw Error('Allow MIDI SysEx in browser permissions.');const ins=Array.from(access.inputs.values()),outs=Array.from(access.outputs.values()),choice=chooseMIDIPorts(ins,outs,(()=>{try{return JSON.parse(localStorage.getItem('fm1-midi-ports')??'null')??undefined;}catch{return undefined;}})(),automatic);inputId=choice.input;outputId=choice.output;access.onstatechange=e=>{const port=(e as MIDIConnectionEvent).port;if(device&&port?.state==='disconnected'&&(port.id===inputId||port.id===outputId)){device.io.close();device=null;state=null;notice='USB disconnected. Local edits retained.';render();}};notice=choice.automatic?'Matching MIDI ports found. Reading device.':ins.length&&outs.length?'Select matching input/output, then Connect selected ports.':'No MIDI ports found. Offline remains available.';return choice.automatic;}


async function connect(automatic=false){if(!access&&!await authorize(automatic))return;if(!access)return;const input=access.inputs.get(inputId),output=access.outputs.get(outputId);if(!input||!output)throw Error('Choose input and output ports.');const transport=new MidiTransport(input as unknown as InputPort,output as unknown as OutputPort);const d:Device=new Device({request:async(op,payload,opts)=>{if(opts?.mutating&&d.readOnly)throw Error('Diagnostics-only connection: complete a successful Pull before device changes');const result=await transport.request(op,payload,opts);if(opts?.mutating&&save)save={...save,state:0};return result;},close:()=>transport.close()});try{await d.handshake();try{localStorage.setItem('fm1-midi-ports',JSON.stringify({input:inputId,output:outputId}));}catch{}}catch(e){d.io.close();device=null;throw e;}device=d;d.readOnly=true;state=null;save=null;norProject=null;sampleNorReports=[];norProjectBackup=null;norSampleBackups=[];try{save=await d.saveStatus();const r=await d.pull(p),list=await d.sampleList();state=r.state;lastRevision=state.revision;deviceSamples=list;if(!dirty){p=r.project;persist();}d.readOnly=false;notice=dirty?'Device read; local edits retained. Pull or Sync explicitly.':'Connected; device runtime read. No persistent write.';}catch(e){error='Diagnostics-only: runtime state could not be read. '+String(e instanceof Error?e.message:e);notice='Diagnostics and raw backups remain available. Complete a successful Pull to enable device changes.';}}

function range(label:string,key:string,value:number,min:number,max:number,attr=''){return `<label class="knobfield"><span class="top">${label}<span class="dial" aria-hidden="true"></span></span><output>${value}</output><input type="range" aria-label="${label}" min="${min}" max="${max}" value="${value}" data-key="${key}" ${attr} ${disabled()}></label>`;}

function pads(){return `<div class="pads">${p.pads.map((pad,l)=>`<button class="pad ${p.selectedPad===l?'active':''}" data-action="pad" data-i="${l}" aria-label="Pad ${l+1} ${esc(name(pad.sampleId))}"><span class="num">${String(l+1).padStart(2,'0')}</span><b>${esc(name(pad.sampleId))}</b><small>${pad.mute?'MUTED':`LEVEL ${pad.level} · PAN ${pad.pan}`}</small></button>`).join('')}</div>`;}

function padFields(){const a=p.pads[p.selectedPad];return `<div class="padcontrols">${range('LEVEL','level',a.level,0,127)}${range('PAN','pan',a.pan,-64,63)}${range('TUNE','tune',a.tune,-24,24)}${range('START %','start',a.start,0,99)}${range('END %','end',a.end,1,100)}${range('DECAY','decay',a.decay,0,127)}</div>`;}

function norPanel(){const capable=!!device?.caps?.norDiagnostics;return `<h3>Read-only NOR diagnosis</h3><p>Read classifications and download original bytes without authorizing a write. AUTOSAVE A/B is 8 KiB total: two separate 4 KiB sectors. Four physical sample banks are 80 KiB each.</p><div class="actions">${button('nor-report','Read AUTOSAVE A/B classification',capable?'':'disabled')}${button('nor-autosave-backup','Download AUTOSAVE raw + report',capable?'':'disabled')}${button('nor-sample-backup','Download sample banks + report',capable?'':'disabled')}</div>${norProjectBackup?`<div class="actions">${button('nor-copy-download','Raw A/B pair .bin','data-i="2"')}${button('nor-copy-download','Raw AUTOSAVE A .bin','data-i="0"')}${button('nor-copy-download','Raw AUTOSAVE B .bin','data-i="1"')}</div>`:''}${norSampleBackups.length?`<div class="actions">${norSampleBackups.map(b=>button('nor-bank-download','Raw bank '+(b.bank+1)+' .bin',`data-i="${b.bank}"`)).join('')}</div>`:''}${!capable?'<p class="note">Read-only NOR extension is unavailable on this firmware. The existing A/B backup below is a separate, owner-triggered recovery preparation; connecting never starts it.</p>':''}${norProject?`<div class="inset"><strong>AUTOSAVE pair CRC32 ${hex(norProject.pairCRC32)}</strong>${norProject.copies.map(c=>`<p><b>Copy ${c.copy?'B':'A'} / ${hex(c.offset)} / ${esc(c.stateName)} / ${esc(c.formatName)}</b><br>${esc(c.reason)}<br>Sequence ${c.sequence}; payload ${c.length} B; raw CRC32 ${hex(c.rawCRC32)}<br><small>Header: ${esc(c.rawHeaderHex)}<br>Payload magic: ${hex(c.payloadMagic)}; prefix: ${esc(c.payloadPrefixHex)}</small></p>`).join('')}</div>`:''}${sampleNorReports.length?`<div class="seqwrap"><table><thead><tr><th>USER / bank / offset</th><th>Format and protection</th><th>References</th></tr></thead><tbody>${sampleNorReports.map(r=>`<tr><td>USER ${r.slot+1} / bank ${r.bank+1}<br>${hex(r.offset)} / ${r.length} B</td><td><strong>${esc(r.formatName)}</strong><br>${esc(r.reason)}</td><td>Live ${hex(r.liveLaneMask)} / USER kits ${hex(r.userKitMask)}<br>${esc(r.dependencyReason)}</td></tr>`).join('')}</tbody></table></div>`:''}<p class="note">Protection flags describe application content/overlap policy, not physical flash BP bits. Unknown SLG2 data is signature-only and stays protected. A legacy or unknown AUTOSAVE can also prevent dependency proof for otherwise empty sample slots. No automatic migration or erase.</p>`;}
function selectedSampleNor(){const r=sampleNorReports.find(x=>x.slot===selectedSample-55);return `<div class="actions">${button('nor-sample-report','Read selected slot protection',device?.caps?.norDiagnostics&&selectedSample>=55?'':'disabled')}</div>${r?`<p class="note"><b>${esc(r.formatName)} / ${hex(r.offset)}</b><br>${esc(r.reason)}<br>${esc(r.dependencyReason)}; live lane mask ${hex(r.liveLaneMask)}, USER kit mask ${hex(r.userKitMask)}.</p>`:''}`;}
function norReportEnvelope(){return {format:'FM1-NOR-DIAGNOSTICS',version:1,device:device?.caps,save,readOnly:true,hardwareVerification:false,autosave:norProject,samples:sampleNorReports,automaticMigration:false};}
function dashboard(){return `<div class="grid"><section class="lcd"><span class="micro">Persistent state / actual device</span><div class="statusbig">${!device?'OFFLINE':save?.state===1?'SAVED':save?.state===2?'NO SAVE':'WAIT'}</div><p>${!device?'No device connected. Offline edits stay in this browser and exported files.':save?.state===2?esc([save.name,saveProtectionReason(save,norProject)].filter(Boolean).join(' — ')):save?.state===1?'Last checked DEVICE snapshot is durable. Local dirty data may differ.':'Runtime awaits safe STOP, idle and write interval.'}</p>${[['Identity',device?.caps?.identity??'—'],['Firmware',device?.caps?.firmware??'—'],['Protocol','Drum 1 / FL extension 80'],['Wire format',device?'DRM'+device.caps?.wire:'DRM1–DRM6'],['User samples',String(userSlots())],['Project',state?String(state.project+1):'—'],['Last error',save?save.name+' / raw '+save.raw:'Not read'],['JEDEC',save?.jedec?'0x'+save.jedec.toString(16).toUpperCase():'Not read']].map(([k,v])=>`<div class="stat"><span>${k}</span><strong>${esc(v)}</strong></div>`).join('')}<div class="actions">${button('save-auto','Request autosave',offline()?'disabled':'')}${button('diag','Read diagnostics',offline()?'disabled':'')}</div></section><section class="card"><h3>Working project</h3><label class="field">Project name<input data-project="name" value="${esc(p.name)}" maxlength="40"></label><p class="muted">8 pads / 6 voices / 55 embedded sources / ${userSlots()} user slots. Factory templates remain read-only ROM.</p><div class="actions">${button('export','Export local')}${button('import','Import local')}${button('pull','Pull device',offline()?'disabled':'')}${button('sync','Sync runtime / STOP',offline()?'disabled':'')}</div><div class="inset"><h3>Transport</h3><div class="actions">${button('play','Play',offline()?'disabled':'')}${button('stop','Stop',offline()?'disabled':'')}${button('record','Record',offline()?'disabled':'')}</div><small>${state?.playing?'DEVICE PLAYING':'DEVICE STOPPED / OFFLINE'}</small></div><p class="note">ACK is runtime acceptance, not a NOR commit. WAIT follows safe STOP/idle and the 20-second interval. SAVE FAILED keeps your local data visible.</p></section><section class="card wide">${norPanel()}<h3>Storage diagnosis & proof-gated recovery</h3><p class="muted">Download all 8 KiB before authorizing one repair. The valid survivor is never erased. Unknown or both-corrupt data remains protected.</p><div class="row"><label class="field">Object<select data-ui="recoveryObject">${[[7,'Working autosave'],[1,'Project 1'],[2,'Project 2'],[3,'Project 3'],[4,'Project 4']].map(([n,s])=>`<option value="${n}"${selected(recoveryObject,n)}>${s}</option>`).join('')}</select></label>${button('recovery-backup','Download A/B backup',offline()?'disabled':'')}${button('recovery-authorize','Authorize one repair',!device||!recovery?'disabled':'')}${button('recovery-cancel','Cancel backup lock',offline()?'disabled':'')}</div><p class="note">No erase of unknown data. FLASH_NOT_READY or physical write failures require diagnostics; see HARDWARE_SAVE_DIAGNOSTICS.md.</p></section></div>`;}

function kits(){const a=p.pads[p.selectedPad];return `<div class="grid"><section>${pads()}<div class="actions">${button('preview-pad','Browser dry preview')}${button('audition','Device pad audition',offline()?'disabled':'')}</div><p class="muted">Real source ADPCM. Firmware FX and output limiter are not simulated in browser.</p></section><section class="lcd"><h3>Pad ${p.selectedPad+1} / ${esc(name(a.sampleId))}</h3><label class="field">Sample assignment<select data-pad-sample>${Array.from({length:71},(_,i)=>`<option value="${i}"${selected(a.sampleId,i)}${i>=55+userSlots()?' disabled':''}>${i} ${esc(name(i))}</option>`).join('')}</select></label>${padFields()}<label class="field"><span><input type="checkbox" data-mute ${a.mute?'checked':''}> MUTE PAD</span></label></section><section class="card"><h3>Factory templates</h3><div class="kitlist">${FACTORY.map((k,i)=>`<button data-action="factory" data-i="${i}"><b>${k.name}</b><small>8 IDs / neutral / FX OFF</small></button>`).join('')}</div></section><section class="card"><h3>User kits</h3>${p.users.map((k,i)=>`<div class="slot"><div><strong>USER ${String(i+1).padStart(2,'0')}</strong><p>${k?'8 pads + all FX':'EMPTY'}</p></div><div class="row">${button('user-load','Load',`data-i="${i}" ${k?'':'disabled'}`)}${button('user-save','Store current',`data-i="${i}"`)}</div></div>`).join('')}</section></div>`;}


function samples(){const entries=EMBEDDED.filter(s=>category==='ALL'||s.category===category);return `<div class="grid"><section class="lcd"><h3>Source library / 55 + ${userSlots()} USER</h3><div class="actions">${['ALL','KICK','SNARE','HAT','OH','PERC','USER'].map(c=>`<button data-action="category" data-category="${c}" class="${category===c?'primary':''}">${c}</button>`).join('')}</div><div class="sample-list">${category!=='USER'?entries.map(s=>`<button class="sample-item ${s.id===selectedSample?'selected':''}" data-action="sample" data-i="${s.id}"><b>${s.name}</b><span>${s.sampleRate} Hz / ${s.duration.toFixed(2)}s</span></button>`).join(''):''}${category==='ALL'||category==='USER'?Array.from({length:userSlots()},(_,i)=>{const id=55+i,s=p.samples.find(x=>x.id===id),d=deviceSamples.find(x=>x.id===id);return `<button class="sample-item ${id===selectedSample?'selected':''}" data-action="sample" data-i="${id}"><b>${esc(name(id))}</b><span>${sampleLocked(id)?'PROTECTED / OVERLAP':s?'LOCAL':d?.flags&&d.flags&2?'DEVICE':'EMPTY / MISSING'}</span></button>`;}).join(''):''}</div></section><section><h3>${esc(name(selectedSample))}</h3><canvas id="wave" class="wave" aria-label="Actual sample waveform"></canvas><div class="actions">${button('preview-source','Dry preview')}${button('source-audition','Device source preview',offline()?'disabled':'')}${button('assign','Assign pad')}${button('export-wav','Export WAV')}</div><label class="field">Destination pad<select data-selected-pad>${p.pads.map((_,i)=>`<option value="${i}"${selected(i,p.selectedPad)}>PAD ${i+1}</option>`).join('')}</select></label><div id="drop" class="drop">DROP WAV HERE / <input id="wav-file" type="file" accept="audio/wav,.wav" aria-label="Import WAV"></div>${wav?`<div class="row"><label class="field">Start / sec<input type="number" data-ui="trimStart" min="0" max="${wav.duration}" step="0.001" value="${trimStart}"></label><label class="field">End / sec<input type="number" data-ui="trimEnd" min="0" max="${wav.duration}" step="0.001" value="${trimEnd}"></label><label class="field">Rate / Hz<select data-ui="importRate">${[8000,16000,22050,44100].map(r=>`<option${selected(r,importRate)}>${r}</option>`).join('')}</select></label></div><div class="actions">${button('prepare-wav','Mono / trim / encode IMA')}${button('auto-fit-quality','Auto-fit · 22 kHz (trim)')}${button('auto-fit-duration','Auto-fit · keep length')}</div><small>${esc(wav.name)} / ${wav.channels.length} channels / ${wav.duration.toFixed(3)} sec</small>`:''}<div class="card" style="margin-top:20px"><h3>User sample slot ${Math.max(1,selectedSample-54)}</h3><label class="field">User slot<select data-ui="userSample">${Array.from({length:16},(_,i)=>`<option value="${55+i}"${selected(selectedSample,55+i)}${i>=userSlots()?' disabled':''}>USER ${i+1} / ID ${55+i}${i>=userSlots()?' / UNSUPPORTED':''}</option>`).join('')}</select></label><p class="muted">${userSlots()} one-zone slots / ${userCapacity().toLocaleString()} ADPCM bytes for new uploads to this slot / ${(userCapacity()*2/22050).toFixed(2)}s at 22.05kHz. START/END/Tune/Decay and six voices use the existing decoder.</p><div class="actions">${button('upload','Upload user sample',offline()||selectedSample<55||selectedSample>=55+userSlots()||sampleLocked(selectedSample)?'disabled':'')}${button('download-sample','Backup device slot',offline()||selectedSample<55||selectedSample>=55+userSlots()?'disabled':'')}${button('delete-local','Remove local source',selectedSample<55?'disabled':'')}${button('delete-device','Delete device slot',offline()||selectedSample<55||selectedSample>=55+userSlots()||sampleLocked(selectedSample)?'disabled':'')}</div>${selectedSampleNor()}<p class="note">Occupied slots require downloaded backup and confirmation. Live, USER and both persisted rollback copies count as dependencies. Unknown / multizone legacy data remains protected. On 16-slot firmware the same four regions are shared; a large legacy source can lock overlapping slots. No automatic conversion or erase. Empty slots upload directly; occupied slots are backed up before explicit replacement.</p></div><div class="card" style="margin-top:20px"><h3>Sample library backup</h3><p>Export local sources and, when connected, every raw device sample slot with metadata and CRC. Import keeps the complete archive locally; restore uploads only validated one-zone sources through the normal guards.</p><div class="actions">${button('library-export','Export library')}${button('library-import','Import library')}${button('library-restore','Restore imported sources',offline()||!libraryArchive?'disabled':'')}</div><p class="note">${libraryArchive?`${libraryArchive.localSources.length} local sources / ${libraryArchive.deviceSnapshot?.slots.length??0} raw device slots retained.`:'No imported archive.'} Unknown or multizone raw records are preserved in the file, never written as raw NOR. Dependencies, capacity and overlap protection can block individual restores. Project references require a separate checked sync.</p></div></section></div>`;}
function fx(master=false){const lane=master?8:p.selectedPad,f=p.fx[lane],names=master?MASTER_FX:LANE_FX,params=(master?MASTER_PARAMS:LANE_PARAMS)[f.type];return `<section class="lcd"><div class="row"><h2>${master?'MASTER OUTPUT':`LANE ${lane+1} / ${esc(name(p.pads[lane].sampleId))}`}</h2><span class="badge right">${f.type?'ON':'OFF'}</span></div><div class="row">${!master?`<label class="field">Lane<select data-selected-pad>${p.pads.map((_,i)=>`<option value="${i}"${selected(i,lane)}>LANE ${i+1}</option>`).join('')}</select></label>`:''}<label class="field">Effect<select data-fx-type data-bus="${lane}">${names.map((n,i)=>`<option value="${i}"${selected(i,f.type)}>${n}</option>`).join('')}</select></label>${button('fx-off','FX off',`data-i="${lane}"`)}</div><div class="padcontrols">${params.map((label,i)=>range(label,'fx',f.p[i],0,100,`data-bus="${lane}" data-param="${i}" ${!f.type?'disabled':''}`)).join('')}</div><p class="note">One effect per lane / master. Four normalized firmware controls update live. Enum/frequency mapping remains in the actual DSP. Browser preview is dry, not approximate firmware processing.</p></section>`;}
function seq(){const start=p.bank*16,ev=p.pattern[eventStep][p.selectedPad];return `<section class="lcd"><div class="row"><h2>Pattern / ${start+1}-${start+16}</h2><div class="row right">${button('play','Play',offline()?'disabled':'')}${button('stop','Stop',offline()?'disabled':'')}${button('record','REC',offline()?'disabled':'')}</div></div><div class="row"><label class="field">Bank<select data-project="bank">${[0,1,2,3].map(n=>`<option value="${n}"${selected(n,p.bank)}>${n*16+1}-${n*16+16}</option>`).join('')}</select></label><label class="field">Length<input type="number" min="1" max="64" data-project="length" value="${p.length}"></label><label class="field">BPM<input type="number" min="40" max="240" data-project="bpm" value="${p.bpm}"></label><label class="field">Swing<input type="number" min="0" max="100" data-project="swing" value="${p.swing}"></label><label class="field">QTZ strength<input type="number" min="0" max="100" data-project="qtz" value="${p.qtz}"></label></div><div class="seqwrap"><div class="seq"><div class="seqnum">8 LANES / 6 VOICES</div>${Array.from({length:16},(_,i)=>`<div class="seqnum">${start+i+1}</div>`).join('')}${p.pads.map((pad,l)=>`<button class="lane-label ${l===p.selectedPad?'active':''}" data-action="pad" data-i="${l}">${l+1} ${esc(name(pad.sampleId))}</button>${Array.from({length:16},(_,i)=>{const e=p.pattern[start+i][l];return `<button class="step ${e.on?'on':''} ${eventStep===start+i&&l===p.selectedPad?'selected':''}" data-action="step" data-lane="${l}" data-i="${start+i}" aria-label="Lane ${l+1} step ${start+i+1} ${e.on?'on':'off'}" aria-pressed="${e.on}"><i></i>${e.raw?e.raw:''}</button>`;}).join('')}`).join('')}</div></div><div class="row"><label class="field">Lane ${p.selectedPad+1} / step ${eventStep+1}<select data-event="level">${['NORMAL','GHOST','SOFT','HARD'].map((n,i)=>`<option value="${i}"${selected(ev.level,i)}>${n}</option>`).join('')}</select></label><label class="field">Ratchet<select data-event="ratchet">${[0,1,2,3].map(i=>`<option value="${i}"${selected(ev.ratchet,i)}>${i+1}x</option>`).join('')}</select></label><label class="field">Timing / 1/64 step<input type="number" min="-32" max="31" data-event="raw" value="${ev.raw}"></label></div><p class="note">Pattern writes require STOP. Raw timing is independent of QTZ. Transport status is read from FM1; no browser playhead is invented. QTZ / record preferences retain existing persistence scope.</p></section>`;}
function projects(){return `<div class="grid"><section class="card"><h3>Local editor project</h3><p>Export includes pads, FX, pattern/raw timing, four USER kits, local ADPCM and MIDI preferences, protected by CRC.</p><div class="actions">${button('export','Export .json')}${button('import','Import .json')}</div><h3>Working project / device</h3><div class="actions">${button('backup-working','Backup current DRM',offline()?'disabled':'')}</div><p class="note">DRM1-DRM6 restore checks magic, length and CRC. Firmware validates every field. FUN/unknown raw backups remain intact.</p></section><section class="lcd"><h3>Four independent device slots</h3>${[0,1,2,3].map(i=>`<div class="slot"><div><strong>${i+1} / PROJECT</strong><p>${!state?'CONNECT TO READ':state.slots&(1<<i)?'OCCUPIED / MAY BE PROTECTED':'EMPTY'}</p></div><div class="actions">${button('project-save','Save',`data-i="${i}" ${offline()?'disabled':''}`)}${button('project-load','Load',`data-i="${i}" ${offline()?'disabled':''}`)}${button('project-backup','Backup',`data-i="${i}" ${offline()?'disabled':''}`)}</div></div>`).join('')}</section><section class="card wide"><h3>Restore checked DRM backup</h3><div class="row"><label class="field">Destination<select data-ui="projectSlot">${[0,1,2,3,4].map(i=>`<option value="${i}"${selected(i,projectSlot)}>${i===4?'Working runtime':'PROJECT '+(i+1)}</option>`).join('')}</select></label><input id="drm-file" type="file" accept=".drm,.bin" aria-label="Restore DRM backup" ${offline()?'disabled':''}></div><p class="note">Existing data is downloaded before confirmed overwrite. Runtime restore and SAVE are separate. RC2 cannot read DRM6 user references.</p></section></div>`;}
function settings(){return `<div class="grid"><section class="lcd"><h3>MIDI routing</h3><div class="row">${[['channel','DRUM CHANNEL',Array.from({length:17},(_,i)=>[i,i?String(i):'OFF'])],['sync','CLOCK',[[0,'INTERNAL'],[1,'USB'],[2,'TRS']]],['input','INPUT',[[0,'NOTES'],[1,'CLOCK ONLY'],...Array.from({length:16},(_,i)=>[i+2,'CH '+(i+1)])]],['output','OUTPUT',[[0,'OFF'],[1,'SEQUENCER'],[2,'KEYS']]],['other','OTHER CHANNEL',Array.from({length:17},(_,i)=>[i,i?String(i):'SELECTED'])]].map(([key,label,options])=>`<label class="field">${label}<select data-midi="${key}">${(options as (number|string)[][]).map(([v,s])=>`<option value="${v}"${selected(p.midi[key as keyof typeof p.midi],v)}>${s}</option>`).join('')}</select></label>`).join('')}</div><h3>Record session</h3><div class="row">${[['mode','MODE',['OVERDUB','REPLACE']],['grid','GRID',['OFF','1/4','1/8','1/16','1/32']],['count','COUNT-IN',['OFF','1 BAR','2 BARS']],['metro','METRONOME',['OFF','REC','ON']]].map(([key,label,values])=>`<label class="field">${label}<select data-record="${key}">${(values as string[]).map((s,i)=>`<option value="${i}"${selected(p.record[key as keyof typeof p.record],i)}>${s}</option>`).join('')}</select></label>`).join('')}</div><div class="actions">${button('settings-send','Apply settings / STOP',offline()?'disabled':'')}</div></section><section class="card"><h3>Compatibility / storage</h3><p>FL SysEx / extension 80 / protocol 1. CRC covers header and payload. 256-byte chunks. Version mismatch disables writes.</p><p>IDs 0-54 stay embedded. IDs 55-58 use fingerprints: missing/replaced audio becomes silent, never an unannounced different sample.</p><p>Four USER kits and four projects preserve A/B. Diagnostics stay in RAM.</p><div class="actions">${button('diag','Export diagnostics',offline()?'disabled':'')}</div><p class="note">Web MIDI SysEx permission and a compatible secure-context browser are required. Offline creation and real dry source previews work without FM1. Mock PASS is not hardware PASS.</p></section></div>`;}
function render(){app.innerHTML=`<div class="app"><header><div class="brand"><div class="mark">FM1<br>DRUM OS</div><div><h1>DRUM WORKSTATION</h1><div class="tagline">WEB EDITOR / USB MIDI / 1.0.0-rc.1</div></div></div><div class="connection"><span class="micro"><i class="led ${device?'on':''}"></i>${device?'FM1 CONNECTED':'OFFLINE LOCAL'}</span>${button(device?'disconnect':'connect',device?'Disconnect':access?'Connect selected ports':'Connect USB MIDI',disabled())}</div></header><div class="shell"><nav aria-label="Editor pages">${pages.map((s,i)=>`<button class="${page===i?'active':''}" data-action="page" data-i="${i}"><span>${String(i+1).padStart(2,'0')}</span>${s}</button>`).join('')}<div class="navfoot">8 PADS / 6 VOICES<br>55 EMBEDDED SOURCES<br>${userSlots()} USER SAMPLE SLOTS<br><br>OFFLINE FIRST<br>ACK IS NOT NOR COMMIT</div></nav><main class="workspace"><div class="viewhead"><div><div class="eyebrow">FM1 / ${String(page+1).padStart(2,'0')} / ${dirty?'LOCAL DIRTY':'LOCAL READY'}</div><h2>${pages[page]}</h2><p>${esc(p.name)} / ${esc(p.kitName)} / ${p.bpm} BPM</p></div><div class="actions">${button('export','Export local')}${button('sync','Sync runtime',offline()?'disabled':'')}</div></div>${access&&!device?`<section class="ports card"><div class="row"><label class="field">MIDI input<select data-port="input">${Array.from(access.inputs.values()).map(v=>`<option value="${esc(v.id)}"${selected(v.id,inputId)}>${esc(v.name??v.id)}</option>`).join('')}</select></label><label class="field">MIDI output<select data-port="output">${Array.from(access.outputs.values()).map(v=>`<option value="${esc(v.id)}"${selected(v.id,outputId)}>${esc(v.name??v.id)}</option>`).join('')}</select></label></div></section>`:''}${error?`<div class="error" role="alert">${esc(error)} ${button('dismiss','Dismiss')}</div>`:''}${busy?`<div class="progress"><i style="width:${Math.max(4,progress*100)}%"></i></div>`:''}${[dashboard,kits,samples,()=>fx(false),()=>fx(true),seq,projects,settings][page]()}</main></div><div class="statusbar" id="status"></div><footer>FM1 DRUM OS / 1.0.0-rc.1 / GPL-3.0-only. Source, license and attribution notices are included in the documentation.</footer></div><input type="file" id="project-file" accept="application/json,.json" hidden><input type="file" id="library-file" accept="application/json,.json" hidden>`;status();if(page===2)void wave();}
async function loadWav(file:File){if(file.size>60_000_000)throw Error('WAV too large; trim before import.');const raw=await file.arrayBuffer();if(raw.byteLength<44||ascii(new Uint8Array(raw,0,4))!=='RIFF'||ascii(new Uint8Array(raw,8,4))!=='WAVE')throw Error('Choose a RIFF WAV.');const b=await audioContext().decodeAudioData(raw);wav={channels:Array.from({length:b.numberOfChannels},(_,i)=>new Float32Array(b.getChannelData(i))),rate:b.sampleRate,duration:b.duration,name:file.name};trimStart=0;trimEnd=b.duration;notice='Decoded locally. Select USER slot and trim before encoding.';}
async function backupSample(slot:number){if(!device)throw Error('Connect first');const raw=await device.backup(2,slot,n=>{progress=n;status();});download(raw,`fm1-user-${slot+1}-raw-backup.bin`);const decoded=sourceFromRaw(raw,slot);if(decoded&&!p.samples.some(s=>s.id===decoded.source.id)){p.samples.push(decoded.source);persist();}return raw;}


async function action(a:string,i:number,el:HTMLElement){switch(a){
case'page':page=i;error='';render();return;case'pad':p.selectedPad=i;selectedSample=p.pads[i].sampleId;render();return;case'category':category=el.dataset.category??'ALL';render();return;case'sample':selectedSample=i;render();return;case'dismiss':error='';render();return;
case'library-export':await run(async()=>{libraryArchive=device?await captureLibrary(device,p.samples,n=>{progress=n;status();}):{localSources:clone(p.samples),deviceSnapshot:libraryArchive?.deviceSnapshot};download(exportLibrary(libraryArchive),'fm1-sample-library.fm1lib.json','application/json');notice=device?'Full sample-slot library exported with CRC. No device write.':'Local library exported; imported raw snapshot retained.';});return;
case'library-import':document.querySelector<HTMLInputElement>('#library-file')?.click();return;
case'library-restore':if(device&&libraryArchive&&confirm('Restore validated sources from this archive? Empty slots need no backup. Each occupied target requires its own downloaded backup and confirmation. Protected/dependent slots remain blocked.'))await run(async()=>{const results=await restoreLibrary(device!,libraryArchive!,async(id,raw)=>{download(raw,`fm1-user-${id-54}-before-library-restore.bin`);return confirm(`Complete backup downloaded for USER ${id-54}. Replace this occupied sample if firmware dependency checks permit it?`);},n=>{progress=n;status();});const pending=bindLibraryRestore(p,libraryArchive!,results);deviceSamples=await device!.sampleList();changed();download(JSON.stringify({results,localConflicts:pending,rawBankRestore:false},null,2),'fm1-library-restore-results.json','application/json');notice=`Library sources: ${results.filter(r=>r.status==='restored').length} restored / ${results.filter(r=>r.status==='already present').length} already present / ${results.filter(r=>r.status==='failed'||r.status==='skipped').length} blocked or skipped. Raw unknown records retained only in archive. ${pending} pending local sources kept unbound; upload them explicitly before Sync.`;});return;
case'export':download(exportProject(p),p.name.replace(/[^\w-]/g,'_')+'.fm1.json','application/json');return;case'import':document.querySelector<HTMLInputElement>('#project-file')?.click();return;
case'preview-pad':await preview(p.pads[p.selectedPad].sampleId,p.pads[p.selectedPad]);return;case'preview-source':await preview(selectedSample);return;case'connect':await run(connect);return;
case'disconnect':if(device){void device.cancelRecovery().catch(()=>{});device.io.close();}device=null;state=null;recovery=null;notice='Disconnected. Local edits retained.';render();return;
case'pull':if(dirty&&!confirm('Replace local state with device runtime? Export first if needed.'))return;await run(pull);return;
case'sync':if(device)await run(async()=>{await device!.push(p);dirty=false;runtimeAck=true;persist();notice='Runtime synchronized. Await SAVED separately.';save=await device!.saveStatus();});return;
case'save-auto':if(device)await run(async()=>{save=await device!.requestSave();notice='Requested; safe idle and write interval still apply.';});return;
case'diag':if(device)await run(async()=>{save=await device!.saveStatus();let runtimeReadError:string|null=null;try{state=await device!.state();}catch(e){state=null;runtimeReadError=String(e instanceof Error?e.message:e);}download(JSON.stringify({device:device!.caps,state,save,runtimeReadError,diagnosticsOnly:device!.readOnly,readOnly:true,hardwareVerification:false,nor:norReportEnvelope()},null,2),'fm1-save-diagnostics.json','application/json');});return;
case'play':case'stop':case'record':if(device)await run(async()=>{await device!.transport(a==='stop'?0:a==='play'?1:2);state=await device!.state();});return;
case'factory':factory(p,i);changed();if(device)await run(async()=>{await device!.io.request(OP.FACTORY,Uint8Array.of(0,i),{mutating:true});runtimeAck=true;});else render();return;
case'user-save':p.users[i]={pads:clone(p.pads),fx:clone(p.fx)};changed();if(device)await run(async()=>{await device!.setUser(i,p.users[i]);runtimeAck=true;notice='USER runtime ACK. Autosave is separately verified.';});else render();return;
case'user-load':if(!p.users[i])return;p.pads=clone(p.users[i]!.pads);p.fx=clone(p.users[i]!.fx);p.kitName='USER '+(i+1);changed();if(device)await run(async()=>{await device!.io.request(OP.FACTORY,Uint8Array.of(1,i),{mutating:true});runtimeAck=true;});else render();return;
case'audition':if(device)await run(async()=>{await device!.setPad(p.selectedPad,p.pads[p.selectedPad]);await device!.audition(p.selectedPad);});return;case'source-audition':if(device)await run(()=>device!.sourceAudition(selectedSample));return;
case'assign':{const pad=p.pads[p.selectedPad],d=deviceSamples.find(x=>x.id===selectedSample);pad.sampleId=selectedSample;pad.ref=selectedSample<55?0:d?.crc??0;p.kitName='CUSTOM';changed();const l=p.selectedPad;live('pad'+l,d=>d.setPad(l,p.pads[l]));render();return;}
case'fx-off':p.fx[i]={type:0,p:[0,0,0,0]};changed();live('fx'+i,d=>d.setFX(i,p.fx[i]));render();return;
case'step':p.selectedPad=Number(el.dataset.lane);eventStep=i;p.pattern[i][p.selectedPad].on=!p.pattern[i][p.selectedPad].on;changed();live('pattern'+p.bank,d=>d.setPattern(p,p.bank*16,16));render();return;
case'prepare-wav':prepareImported();return;
case'auto-fit-quality':prepareImported('quality');return;
case'auto-fit-duration':prepareImported('duration');return;
case'upload':if(device&&selectedSample>=55)await run(async()=>{const sample=p.samples.find(s=>s.id===selectedSample);if(!sample)throw Error('Import and encode a local sample first.');deviceSamples=await device!.sampleList();const d=deviceSamples.find(s=>s.id===selectedSample),replace=!!(d&&d.flags&2);if(sampleLocked(selectedSample))throw Error('Protected or overlapping slot; no upload requested.');if(replace){await backupSample(selectedSample-55);if(!confirm('Full raw backup downloaded. Replace this known sample only if the device confirms no dependencies?'))return;}const fp=await device!.upload(sample,replace,n=>{progress=n;status();});p.pads.forEach(a=>{if(a.sampleId===sample.id)a.ref=fp;});p.users.forEach(k=>k?.pads.forEach(a=>{if(a.sampleId===sample.id)a.ref=fp;}));deviceSamples=await device!.sampleList();changed();notice='CRC-verified sample committed. Sync pad references separately.';});return;
case'download-sample':if(selectedSample>=55)await run(()=>backupSample(selectedSample-55));return;
case'delete-local':{const refs=references(p,selectedSample);if(refs.length)throw Error('Referenced locally: '+refs.join(', '));p.samples=p.samples.filter(s=>s.id!==selectedSample);changed();render();return;}
case'delete-device':if(device&&selectedSample>=55)await run(async()=>{await backupSample(selectedSample-55);if(!confirm('Raw backup downloaded. Delete only if no live or persisted dependencies?'))return;await device!.deleteSample(selectedSample-55);deviceSamples=await device!.sampleList();notice='Deleted after backup and dependency checks.';});return;
case'export-wav':{const s=await source(selectedSample);download(new Uint8Array(wavPCM16(s.pcm,s.rate)),name(selectedSample)+'.wav','audio/wav');return;}
case'project-save':if(device&&confirm(`Save device runtime to PROJECT ${i+1}? Existing project will be backed up before overwrite.`))await run(async()=>{if(state&&state.slots&(1<<i))download(await device!.backup(1,i),`fm1-project-${i+1}-before-save.bin`);await device!.requestSave(i);state=await device!.state();notice='Manual SAVE completed. Working autosave status is independent.';});return;
case'project-load':if(device&&confirm(`Load PROJECT ${i+1} into device runtime? Local editor is retained until Pull.`))await run(async()=>{await device!.load(i);state=await device!.state();notice='Loaded. Pull device to update local editor.';});return;
case'project-backup':if(device)await run(async()=>download(await device!.backup(1,i),`fm1-project-${i+1}.drm`));return;case'backup-working':if(device)await run(async()=>download(await device!.backup(0,0),'fm1-working.drm'));return;
case'settings-send':if(device)await run(async()=>{const m=p.midi,r=p.record;await device!.settings(concat(Uint8Array.of(m.channel,m.sync,m.input,m.output,m.other,r.metro,r.mode,r.grid,r.count),le16(p.bpm),Uint8Array.of(p.swing,p.qtz)));runtimeAck=true;notice='Applied. Session-only fields retain existing firmware semantics.';});return;
case'nor-copy-download':if(norProjectBackup){download(i===2?norProjectBackup:norProjectBackup.slice(i*4096,(i+1)*4096),i===2?'fm1-autosave-AB-raw.bin':`fm1-autosave-${i?'B':'A'}-raw.bin`);}return;
case'nor-bank-download':{const b=norSampleBackups.find(x=>x.bank===i);if(b)download(b.data,`fm1-sample-bank-${i+1}-${hex(b.offset)}-raw.bin`);return;}
case'nor-report':if(device)await run(async()=>{norProject=await device!.norProjectReport(7);save=await device!.saveStatus();notice='Read-only AUTOSAVE classification received. No write, recovery authorization or erase.';});return;
case'nor-autosave-backup':if(device)await run(async()=>{const r=await device!.exportNorProject(7,n=>{progress=n;status();});norProject=r.report;norProjectBackup=r.data;save=await device!.saveStatus();download(JSON.stringify({...norReportEnvelope(),rawEncoding:'base64',rawPair:toBase64(r.data)},null,2),'fm1-autosave-NOR-backup.json','application/json');notice='Verified full 8 KiB AUTOSAVE pair and report downloaded in one archive. Separate raw .bin buttons are available. Device unchanged; no recovery authorized.';});return;
case'nor-sample-report':if(device&&selectedSample>=55)await run(async()=>{const r=await device!.norSampleReport(selectedSample-55);sampleNorReports=sampleNorReports.filter(x=>x.slot!==r.slot);sampleNorReports.push(r);sampleNorReports.sort((a,b)=>a.slot-b.slot);notice='Read-only slot protection and reference diagnosis received.';});return;
case'nor-sample-backup':if(device)await run(async()=>{const r=await device!.exportNorSampleBanks(n=>{progress=n;status();});sampleNorReports=r.reports;norSampleBackups=r.banks;download(JSON.stringify({...norReportEnvelope(),rawEncoding:'base64',banks:r.banks.map(({data,...meta})=>({...meta,length:data.length,raw:toBase64(data)}))},null,2),'fm1-sample-NOR-backup.json','application/json');notice='All four full raw banks and all logical-slot diagnoses downloaded in one CRC-verified archive. Separate bank .bin buttons are available. No migration or erase authorized.';});return;
case'recovery-backup':if(device)await run(async()=>{const r=await device!.recoveryBackup(recoveryObject,n=>{progress=n;status();});download(r.data,`fm1-object-${recoveryObject}-AB-backup.bin`);recovery={crc:r.crc,token:r.token};notice='8 KiB verified/downloaded. Review diagnostics before authorizing.';});return;
case'recovery-authorize':if(device&&recovery&&confirm('I saved the complete 8 KiB backup. Authorize ONE repair of an authenticated damaged copy, preserving the valid survivor? Unknown or both-corrupt data remains blocked.'))await run(async()=>{await device!.authorizeRecovery(recovery!.token,recovery!.crc);await device!.requestSave(recoveryObject===7?255:recoveryObject-1);recovery=null;save=await device!.saveStatus();notice='Authorized one repair. Await verified SAVED, not merely ACK.';});return;
case'recovery-cancel':if(device)await run(async()=>{await device!.cancelRecovery();recovery=null;notice='Backup lock canceled. No recovery write requested.';});return;
}}
app.addEventListener('click',e=>{const b=(e.target as HTMLElement).closest<HTMLElement>('[data-action]');if(b&&!b.hasAttribute('disabled'))void action(b.dataset.action!,Number(b.dataset.i??0),b).catch(e=>{error=String(e.message??e);render();});});
app.addEventListener('input',e=>{const el=e.target as HTMLInputElement;if(!el.dataset.key)return;const v=Number(el.value);if(el.dataset.key==='fx'){const bus=Number(el.dataset.bus),parameter=Number(el.dataset.param);p.fx[bus].p[parameter]=v;changed();live('fx'+bus,d=>d.setFX(bus,p.fx[bus]));}else{changePad(p,p.selectedPad,el.dataset.key as keyof Pad,v);changed();const lane=p.selectedPad;live('pad'+lane,d=>d.setPad(lane,p.pads[lane]));}const o=el.closest('label')?.querySelector('output');if(o)o.textContent=String(el.dataset.key==='start'?p.pads[p.selectedPad].start:el.dataset.key==='end'?p.pads[p.selectedPad].end:v);});
app.addEventListener('change',e=>{void(async()=>{const el=e.target as HTMLInputElement|HTMLSelectElement;
if(el.id==='project-file'){const f=(el as HTMLInputElement).files?.[0];if(f){if(f.size>2_000_000)throw Error('Project file too large');p=importProject(await f.text());eventStep=p.bank*16;changed();notice='Imported locally. Device unchanged.';render();}return;}
if(el.id==='library-file'){const f=(el as HTMLInputElement).files?.[0];if(!f)return;await run(async()=>{if(f.size>4_000_000)throw Error('Sample library file too large');const imported=importLibrary(await f.text());if(!confirm('Import checked library sources into local editor? Device unchanged; export local work first if needed.'))return;libraryArchive=imported;p.samples=librarySources(imported);const ids=new Set(p.samples.map(s=>s.id));p.pads.forEach(a=>{if(ids.has(a.sampleId))a.ref=0;});p.users.forEach(k=>k?.pads.forEach(a=>{if(ids.has(a.sampleId))a.ref=0;}));changed();notice='Library imported locally with raw snapshot intact. Upload/restore sources before syncing references.';});return;}
if(el.id==='wav-file'){const f=(el as HTMLInputElement).files?.[0];if(f)await run(()=>loadWav(f));return;}
if(el.id==='drm-file'){const f=(el as HTMLInputElement).files?.[0];if(!f||!device)return;await run(async()=>{if(f.size>3840)throw Error('DRM file too large');const data=new Uint8Array(await f.arrayBuffer());verifyProjectWire(data);if(!confirm(`Restore to ${projectSlot===4?'working runtime':'PROJECT '+(projectSlot+1)}?`))return;const old=await device!.backup(projectSlot===4?0:1,projectSlot===4?0:projectSlot).catch(e=>{if(projectSlot!==4&&e instanceof ProtocolError&&e.code===7)return null;throw e;});if(old)download(old,'fm1-before-restore.drm');await device!.restore(projectSlot,data);notice='Checked restore complete. Pull runtime or load the destination slot.';});return;}
if(el.dataset.port){if(el.dataset.port==='input')inputId=el.value;else outputId=el.value;return;}
if(el.dataset.ui){const k=el.dataset.ui,v=Number(el.value);if(k==='userSample'){selectedSample=v;render();return;}else if(k==='trimStart')trimStart=v;else if(k==='trimEnd')trimEnd=v;else if(k==='importRate')importRate=v;else if(k==='projectSlot')projectSlot=v;else if(k==='recoveryObject'){recoveryObject=v;recovery=null;}return;}
if(el.hasAttribute('data-selected-pad')){p.selectedPad=Number(el.value);render();return;}if(el.hasAttribute('data-pad-sample')){selectedSample=Number(el.value);await action('assign',0,el);return;}if(el.hasAttribute('data-mute')){changePad(p,p.selectedPad,'mute',(el as HTMLInputElement).checked);changed();const l=p.selectedPad;live('pad'+l,d=>d.setPad(l,p.pads[l]));return;}
if(el.hasAttribute('data-fx-type')){const bus=Number(el.dataset.bus);p.fx[bus]={type:Number(el.value),p:[50,50,50,50]};if(!p.fx[bus].type)p.fx[bus].p=[0,0,0,0];changed();live('fx'+bus,d=>d.setFX(bus,p.fx[bus]));render();return;}
if(el.dataset.project){const k=el.dataset.project;if(k==='name')p.name=el.value.slice(0,40);else{const ranges:Record<string,[number,number]>={bpm:[40,240],length:[1,64],swing:[0,100],qtz:[0,100],bank:[0,3]},r=ranges[k];if(!r)return;const v=Math.round(Number(el.value));if(!Number.isFinite(v)||v<r[0]||v>r[1])throw Error(`${k} must be ${r[0]}..${r[1]}`);(p as unknown as Record<string,unknown>)[k]=v;if(k!=='bank')live('pattern-global',d=>d.setPattern(p,0,16));}changed();if(k==='bank'){eventStep=p.bank*16+(eventStep%16);render();}else status();return;}
if(el.dataset.event){const k=el.dataset.event as 'level'|'ratchet'|'raw',v=Number(el.value);if(!Number.isInteger(v)||(k==='raw'?(v< -32||v>31):(v<0||v>3)))throw Error('Event bounds');p.pattern[eventStep][p.selectedPad][k]=v;changed();live('pattern'+Math.floor(eventStep/16),d=>d.setPattern(p,Math.floor(eventStep/16)*16,16));return;}
if(el.dataset.midi){p.midi[el.dataset.midi as keyof typeof p.midi]=Number(el.value);changed();return;}if(el.dataset.record){p.record[el.dataset.record as keyof typeof p.record]=Number(el.value);changed();return;}
})().catch(e=>{error=String(e.message??e);render();});});
app.addEventListener('dragover',e=>{if((e.target as HTMLElement).closest('#drop')){e.preventDefault();document.querySelector('#drop')?.classList.add('drag');}});app.addEventListener('dragleave',()=>document.querySelector('#drop')?.classList.remove('drag'));app.addEventListener('drop',e=>{if((e.target as HTMLElement).closest('#drop')){e.preventDefault();const f=e.dataTransfer?.files[0];if(f)void run(()=>loadWav(f));}});
let polling=false;setInterval(()=>{if(!device||busy||polling)return;polling=true;void(async()=>{const d=device!;if(d.readOnly){save=await d.saveStatus();status();return;}const next=await d.state();save=await d.saveStatus();state=next;if(next.revision!==lastRevision){lastRevision=next.revision;if(!dirty){const r=await d.pull(p);p=r.project;persist();render();}else{notice='Device runtime changed; local edits retained. Pull or Sync explicitly.';status();}}else status();})().catch(e=>{error=String(e.message??e);render();}).finally(()=>polling=false);},1500);
window.addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue='';}});
render();

void previouslyGrantedMIDI(navigator).then(granted=>{if(granted&&!device&&!access&&!busy)void run(()=>connect(true));});
